<?php
require_role('admin');$search=trim(substr((string)($_GET['search']??''),0,160));$status=(string)($_GET['status']??'');$w=['1=1'];$p=[];$filters=[];
if($search!==''){$w[]='(i.title LIKE ? OR i.address LIKE ? OR i.id=?)';$p[]='%'.$search.'%';$p[]='%'.$search.'%';$p[]=(int)ltrim($search,'#');}if(in_array($status,staff_statuses(),true)){$w[]='i.status=?';$p[]=$status;}
foreach(['category'=>'category_id','area'=>'area_id','officer'=>'officer_id','team'=>'maintenance_id'] as $key=>$col){$filters[$key]=max(0,(int)($_GET[$key]??0));if($filters[$key]){$w[]='i.'.$col.'=?';$p[]=$filters[$key];}}
foreach(['province'=>'province_id','district'=>'district_id','town'=>'town_id'] as $key=>$column){$filters[$key]=max(0,(int)($_GET[$key]??0));if($filters[$key]){$w[]='i.'.$column.'=?';$p[]=$filters[$key];}}
$sql=' WHERE '.implode(' AND ',$w);$total=(int)q('SELECT COUNT(*) FROM issues i'.$sql,$p)->fetchColumn();$max=max(1,(int)ceil($total/500));$pn=min($max,max(1,(int)($_GET['p']??1)));$rows=q(issue_query().$sql.' ORDER BY i.created_at DESC,i.id DESC LIMIT 500 OFFSET '.(($pn-1)*500),$p)->fetchAll();admin_page_start('Community map','Locate reports by Province, District, Town, officer or maintenance team.',true);
?><form method="get" class="panel admin-filter-grid"><input type="hidden" name="page" value="map"><label>Search reports<input type="search" name="search" value="<?=e($search)?>" maxlength="160" placeholder="Title, location or #ID"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(staff_statuses() as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></label><?php foreach(['category'=>['Category',array_column(categories(),'name','id')],'officer'=>['Officer',array_column(q("SELECT id,name FROM users WHERE role='officer' ORDER BY name")->fetchAll(),'name','id')],'team'=>['Maintenance team',array_column(q("SELECT id,name FROM users WHERE role='maintenance' ORDER BY name")->fetchAll(),'name','id')]] as $key=>$info):?><label><?=$info[0]?><select name="<?=$key?>"><option value="">All</option><?php foreach($info[1] as $id=>$name):?><option value="<?=$id?>" <?=$filters[$key]==$id?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></label><?php endforeach;?><?php geo_filter_controls($filters);?><div class="admin-filter-actions"><button class="button secondary">Apply filters</button><a class="text-link" href="index.php?page=map">Reset</a></div></form>
<details class="admin-map-search"><summary>Find a place or street</summary><?php location_search('community-map');?></details><div class="officer-map-legend" aria-label="Map status colours"><?php foreach(officer_map_colours() as $label=>$colour):?><span><i style="background:<?=$colour?>"></i><?=e($label)?></span><?php endforeach;?></div><div class="regional-map-toolbar"><button type="button" class="button secondary" id="map-show-reports">Show all reports on this page</button><span class="small muted">Select a marker to open report details.</span></div><div id="community-map" class="officer-map" aria-label="Community reports map"></div><script type="application/json" id="map-data"><?=json_encode(array_map(function($i){return ['id'=>$i['id'],'title'=>$i['title'],'status'=>$i['status'],'latitude'=>$i['latitude'],'longitude'=>$i['longitude'],'color'=>officer_map_colours()[$i['status']]??'#697887'];},$rows),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><p class="small muted"><?=count($rows)?> of <?=$total?> reports on this map page. Map / Satellite / Auto modes remain available. Use Reports & export for CSV downloads.</p><details open class="panel section-space"><summary>Report list (<?=count($rows)?>)</summary><?php if($rows)issue_table($rows);else echo '<p class="small muted">No reports match these map filters.</p>';?></details><?php admin_pager($pn,$max,$total);admin_page_end();
